import gurobipy as gp
from gurobipy import GRB
records = LEGACY_RECORDS
capacity_records = [r for r in records if r['source'].endswith('capacity.csv')]
if not capacity_records or 'resource_capacity' not in capacity_records[0]['values']:
    raise ValueError('Missing resource_capacity in capacity.csv')
resource_capacity = float(capacity_records[0]['values']['resource_capacity'])
product_records = [r for r in records if r['source'].endswith('products.csv')]
if len(product_records) != 10:
    raise ValueError('Expected 10 products in products.csv')
item_names = [r['values']['item_name'] for r in product_records]
item_value = {r['values']['item_name']: float(r['values']['item_value']) for r in product_records}
resource_requirement = {r['values']['item_name']: float(r['values']['resource_requirement']) for r in product_records}
m = gp.Model('Bakery_Stocking')
x_vars = m.addVars(item_names, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((item_value[i] * x_vars[i] for i in item_names)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((resource_requirement[i] * x_vars[i] for i in item_names)) <= resource_capacity, name='storage_capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')